import os
import json
from ute_common_abstract_core import logger as core_logger
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ute_ue.config import loggers as ta_ue_logging
from ute_ue.lteue import LteUe
from taf.ue.fastmile.utils import add_interface_trace
from taf.ue.fastmile.datatransfer.iperf_data_transfer import IperfDownLinkDataTransfer, IperfUpLinkDataTransfer
from taf.ue.fastmile.exceptions import UeProxyLogsError
from taf.ue.rpc.jsonrpc import RpcError


class FastmileUe(LteUe):
    def __init__(self, name, ue_pc, configuration):
        """
        :param name:
        :param ue_pc:
        :param configuration:
        """
        self.ue_config_full = configuration
        self.configuration = configuration["configuration"]

        super(FastmileUe, self).__init__(name, self.configuration)

        self.prepared = False
        self.ue_pc = ue_pc
        self.ue_id = self.ue_config_full["ue_manage_ip"]

        self._create_ue_identification()
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self.ue_id})

    def _create_ue_identification(self):
        ue_identification = self.ue_id
        self.ne_id = UeIdentification(identifiers=[('fastmile', ue_identification)],
                                      network_elem_type='UE',
                                      specific_for_tool='fastmile')

    def __str__(self):
        return "{}({})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '')

    def __repr__(self):
        return "{}({}, at {})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '',
                                      hex(id(self)))

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        reserve_ue_config = {'com_port': self.ue_config_full["com_port"],
                             'root_password': self.ue_config_full["root_password"],
                             'version': self.ue_config_full.get('version') or '3.1',
                             'default_user_password': self.configuration.get('default_user_password')}
        self.logger.debug("prepare_ue before calling reserve_ue on taf.ue.proxy")
        self.prepared = self.ue_pc.reserve_ue(ue_id=self.ue_id, ue_config=reserve_ue_config)
        self.logger.debug("prepare_ue after calling reserve_ue on taf.ue.proxy")
        return self.prepared

    @add_interface_trace
    def shutdown(self):
        """Shutdown is triggered at the end of current scope (it depends where Require UE was called)"""
        self.logger.debug('Shutting down the UE.')
        try:
            state = self.ue_pc.release_ue(ue_id=self.ue_id)
        except RpcError as rpc_err:
            self.logger.warning("ue is released abnormally for RpcError: {}".format(str(rpc_err)))
            return True
        except Exception as e:
            self.logger.warning("ue is released abnormally for unexpected exception: {}".format(str(e)))
            return True
        return state

    @add_interface_trace
    def attach(self, timeout=10, **kwargs):
        """
        Perform attach on UE.

        :param timeout: Time during which UE should finish attach procedure(change attach state and connect to cell)
        :param kwargs: UE specific arguments
        :return: None
        """
        response = self.ue_pc.attach_ue(ue_id=self.ue_id, timeout=timeout, **kwargs)
        self.log_ue_info()
        return response

    @add_interface_trace
    def detach(self, timeout=10, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :param timeout: Time during which UE should perform detach
        :param kwargs: UE specific arguments
        :return: None
        """
        return self.ue_pc.detach_ue(ue_id=self.ue_id, timeout=timeout, **kwargs)

    @add_interface_trace
    def log_ue_info(self, info_list=None):
        """
        Logs specified UE information.

        :param info_list: List of information to be logged, None by default,
            - available values (FastMile): ALL, NAME, SERIAL, OS_VERSION, BUILD_VERSION, DEVICE_MODEL, IP, IPS, IMEI,
            PCI
        :return: None
        """
        response = self.get_ue_info(info_list)
        self.logger.info("Log ue info: {}".format(response))

    @staticmethod
    def _get_ue_ip(ips):
        if len(ips) == 0:
            ue_ip = {'ip': None}
        else:
            for ue_if_name, ue_ips in ips.items():
                ue_ip = {'ip': ue_ips[0]}
        return ue_ip

    @add_interface_trace
    def get_ue_info(self, info_list=None):
        """
        Get specified UE information.
        Example:
            ue.get_ue_info('pci')
                --> '305'
            ue.get_ue_info(['pci', 'ips'])
                --> {'pci': '305', 'ips': {'dxdata1': ['10.10.10.10']}}
            ue.get_ue_info('all')
                --> {dict with all available ue information}
        Note: `info_list` is case-insensitive

        :param info_list: one (string) or more than one (list) of following infos, None by default
            - 'ALL' - all the infos from UE
            - 'NAME' - UE description
            - 'SERIAL' - UE serial number
            - 'IMEI' - IMEI number on UE
            - 'BUILD_VERSION' - UE hardware version
            - 'OS_VERSION' - UE software version
            - 'DEVICE_MODEL' - UE device model
            - 'PCI' - UE device pci
            - 'IPS' - returns a dict of apn_name and its ipv4 address, e.g. {"dxdata1": ["100.99.250.145"]}
                TODO ipv6 address if needed
            - 'IP' - returns an ip address in active mobile network (legacy option, IPS is recommended to use instead)
        :return: string value for single info; dict {'info_name': 'info_value'} for multiple infos
        """
        response = self.get_info(info_list)
        self.logger.debug(f"output from get_info: {response}")
        response = list(response.values())[0] if len(response) == 1 else response
        return response

    @add_interface_trace
    def get_info(self, info_list):
        """
        Return information about UE

        :param info_list: one (string) or more than one (list) of infos
        :return: dict {'info_name': 'info_value'}
        """
        if info_list:
            info_list = info_list if isinstance(info_list, list) else [info_list]
            info_list = [str(attr).lower() for attr in info_list]
            info_list = None if 'all' in info_list else info_list
        if info_list:
            self.logger.info('info list is {}'.format(info_list))
            if 'ip' in info_list:
                self.logger.warning("legacy ue 'ip' info will be deprecated, use 'ips' instead")
                temp_info_list = info_list.copy()
                temp_info_list.remove('ip')
                if 'ips' not in temp_info_list:
                    temp_info_list.append('ips')
                response = self.ue_pc.get_ue_info(ue_id=self.ue_id, ue_attributes=temp_info_list)
                ip = self._get_ue_ip(response['ips'])
                response.update(ip)

                if 'ips' not in info_list:
                    response.pop('ips')
            else:
                response = self.ue_pc.get_ue_info(ue_id=self.ue_id, ue_attributes=info_list)
        else:
            response = self.ue_pc.get_ue_info(ue_id=self.ue_id)
            ip = self._get_ue_ip(response['ips'])
            response.update(ip)
        self.logger.debug(json.dumps(response, sort_keys=False, indent=4))
        return response

    @add_interface_trace
    def reboot_ue(self, timeout=120):
        """
        Reboot UE and wait until it is fully functional
        :param timeout - waiting time in seconds for UE after reboot
        :return: None
        """
        self.logger.debug("Executing reboot ue")
        return self.ue_pc.reboot_ue(ue_id=self.ue_id, timeout=timeout)

    @add_interface_trace
    def lock_cell(self, network_technology, pci, arfcn, direction="downlink", band=None):
        """
        Lock LTE(4G) or NR(5G) cell on device
        :param network_technology: network technology, e.g lte or nr.
        :param pci: physical cell id
        :param arfcn: arfcn number
        :param direction: specify the direction, e.g "downlink" or "uplink"
        :param band: band number
        :return: bool, True or False
        """
        network_technology = self._parse_network_technology(network_technology)
        extra_params = {'direction': direction, 'band': band}
        return self.ue_pc.lock_cell(ue_id=self.ue_id,
                                    network_mode=network_technology,
                                    pci=pci,
                                    arfcn=arfcn,
                                    extra_params=extra_params)

    @add_interface_trace
    def unlock_cell(self, network_technology):
        """
        Unlock LTE(4G) or NR(5G) cell on device
        :param network_technology: network technology, e.g lte or nr.
        :return: bool, True or False
        """
        network_technology = self._parse_network_technology(network_technology)
        return self.ue_pc.unlock_cell(ue_id=self.ue_id, network_mode=network_technology)

    def _parse_network_technology(self, network_technology):
        network_technology_lower = network_technology.lower()
        if network_technology_lower in ('nr', 'lte'):
            return network_technology_lower
        else:
            raise NotImplementedError(f"Network technology: {network_technology} is not supported")

    @add_interface_trace
    def get_current_access_technology(self):
        """
        Get the current access technology on device.

        :return: str for current access technology
        """
        return self.ue_pc.get_current_access_technology(ue_id=self.ue_id)

    @add_interface_trace
    def set_access_technology(self, technology, preferred=None):
        """
        Set the access technology on device.

        :param technology: access technology, should be one or more item from the supported technologies:
            "LTE", "NR5GNSA" and "NR5GSA".
            single option: "LTE", "NR5GNSA", "NR5GSA"
            multiple options: ["LTE", "NR5GNSA"], ["LTE", "NR5GSA"], ["NR5GNSA", "NR5GSA"], ["LTE", "NR5GNSA", "NR5GSA"]
        :param preferred: preferred access technology, one of the technology if it contains multiple options.
        :return: None
        """
        self.ue_pc.set_access_technology(ue_id=self.ue_id, technology=technology, preferred=preferred)

    @add_interface_trace
    def lock_band(self, network_technology, band):
        """
        Lock LTE(4G) or NR(5G) band on device
        :param network_technology: network technology, e.g lte or nr.
        :param band: band
        :return: bool, True or False
        """
        return self.ue_pc.lock_band(ue_id=self.ue_id,
                                    network_technology=network_technology,
                                    band=band)

    @add_interface_trace
    def unlock_band(self, network_technology, band=''):
        """
        Unlock LTE(4G) or NR(5G) band on device
        :param network_technology: network technology, e.g lte or nr.
        :param band: band, if not specified, unlock all bands.
        :return: bool, True or False
        """
        return self.ue_pc.unlock_band(ue_id=self.ue_id,
                                      network_technology=network_technology,
                                      band=band)

    @add_interface_trace
    def start_message_logging(self):
        """
        Start message logging.

        :return: bool, True or False
        """
        return self.ue_pc.start_message_logging(ue_id=self.ue_id)

    @add_interface_trace
    def stop_message_logging(self):
        """
        Stop message logging.

        :return: bool, True or False
        """
        return self.ue_pc.stop_message_logging(ue_id=self.ue_id)

    @add_interface_trace
    def set_apn(self, apn_name):
        """
        Set apn on device
        :param apn_name: apn name, e.g wap1.nokia.com.
        :return: None
        """
        return self.ue_pc.set_apn(ue_id=self.ue_id, apn_name=apn_name)

    @add_interface_trace
    def get_apn(self):
        """
        Get apn on device
        :return: None
        """
        return self.ue_pc.get_apn(ue_id=self.ue_id)

    @add_interface_trace
    def set_earfcn_lock(self, network_mode, earfcn, scs=30, **kwargs):
        """
        Lock frequency.
        :param network_mode: Network mode for which to lock the earfcn
        :param earfcn: earfcn number, unlock frequency if earfcn equals to 0
        :param scs: SCS number
        """
        earfcn = 0 if int(earfcn) < 0 else int(earfcn)
        return self.ue_pc.set_earfcn_lock(ue_id=self.ue_id,
                                          network_mode=network_mode,
                                          earfcn=earfcn,
                                          scs=int(scs))

    @add_interface_trace
    def reset_earfcn_lock(self, network_mode):
        """
        Reset lock frequency.
        :param network_mode: Network mode for which to lock the earfcn
        """
        return self.ue_pc.reset_earfcn_lock(ue_id=self.ue_id,
                                            network_mode=network_mode)

    def _remove_local_existing_file(self, file_path):
        if os.path.exists(file_path) and os.path.isfile(file_path):
            self.logger.warning('file "{}" exists, will be removed for recreation.'.format(file_path))
            try:
                os.remove(file_path)
            except Exception as e:
                self.logger.warning("failed to remove local file {} for {}".format(file_path, e))
                return

            if os.path.exists(file_path) and os.path.isfile(file_path):
                raise UeProxyLogsError('failed to remove file "{}".'.format(file_path))

    @add_interface_trace
    def download_ue_proxy_logs_zip(self, zip_name='ue_proxy_logs.zip'):
        """
        Download ue proxy logs with .zip format

        :param zip_name: name of zip file
        :return: None
        """
        if not zip_name.lower().endswith(".zip"):
            zip_name = zip_name + ".zip"

        proxy_logs = self.ue_pc.download_ue_proxy_logs_zip(zip_name=zip_name, request_type="get")
        file_path = os.path.join(core_logger.get_logging_path(), zip_name)

        self._remove_local_existing_file(file_path)
        with open(file_path, 'wb') as zip_file_obj:
            zip_file_obj.write(proxy_logs.content)
        if os.path.exists(file_path) and os.path.isfile(file_path):
            self.logger.debug("ue proxy file '{}' is created.".format(file_path))
            return
        raise UeProxyLogsError("ue proxy file '{}' is not correctly created.".format(file_path))

    @add_interface_trace
    def _create_data_transfer(self, name, dt_definition):
        """
        Creating IperfDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: IperfDataTransfer instance
        """
        if dt_definition.direction == "dl":
            return IperfDownLinkDataTransfer(name, self.ue_pc, self.ue_id, dt_definition, self.configuration)

        if dt_definition.direction == "ul":
            return IperfUpLinkDataTransfer(name, self.ue_pc, self.ue_id, dt_definition, self.configuration)
